css:
.wp { max-width: 880px; margin-inline: auto; }
.wp__head { margin-bottom: var(--os-space-xl); }
.wp__eyebrow { margin: 0 0 var(--os-space-xs); font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: var(--os-type-eyebrow-text-transform, uppercase); color: var(--os-eyebrow-color, var(--os-color-accent)); }
.wp__title { margin: 0 0 var(--os-space-sm); font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h1-font-size); line-height: var(--os-type-h1-line-height); color: var(--os-color-heading); text-wrap: balance; }
.wp__intro { max-width: 36em; font-size: var(--os-type-lead-font-size); line-height: var(--os-type-lead-line-height); color: var(--os-color-text); }
.wp__intro p { margin: 0; }
.wp__wrap { position: relative; }
.wp__rail { position: absolute; left: 23px; top: 24px; bottom: 24px; width: 4px; border-radius: 4px; background: var(--os-color-border); }
.wp__fill { position: absolute; inset: 0; border-radius: 4px; background: var(--os-color-accent); transform-origin: top; transform: scaleY(1); }
.wp__list { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--os-space-xl); }
.wp__step { position: relative; padding-left: 80px; transition: opacity 0.5s var(--os-motion-ease, ease-out), transform 0.5s var(--os-motion-ease, ease-out); }
.wp__dot { position: absolute; left: 0; top: 0; width: 50px; height: 50px; border-radius: 50%; display: grid; place-items: center; font-family: var(--os-font-label); font-size: 18px; font-weight: 500; background: var(--os-color-accent); color: var(--os-color-accent-text); border: 4px solid var(--os-color-background); box-shadow: 0 0 0 2px var(--os-color-accent); transition: background 0.4s ease, color 0.4s ease, box-shadow 0.4s ease, transform 0.4s ease; }
.wp__when { margin: 0 0 var(--os-space-2xs); font-family: var(--os-font-label); font-size: var(--os-type-eyebrow-font-size); letter-spacing: var(--os-type-eyebrow-letter-spacing); text-transform: uppercase; color: var(--os-color-text-muted); padding-top: 4px; }
.wp__steptitle { margin: 0 0 var(--os-space-xs); font-family: var(--os-font-heading); font-weight: var(--os-font-weight-heading); font-size: var(--os-type-h3-font-size); line-height: var(--os-type-h3-line-height); color: var(--os-color-heading); text-wrap: balance; }
.wp__body { max-width: 34em; color: var(--os-color-text); }
.wp__body p { margin: 0; }
.wp--js .wp__fill { transform: scaleY(0); }
.wp--js .wp__step { opacity: 0.3; transform: translateY(var(--os-motion-reveal-distance, 16px)); }
.wp--js .wp__step .wp__dot { background: var(--os-color-surface); color: var(--os-color-text-muted); box-shadow: 0 0 0 2px var(--os-color-border); }
.wp--js .wp__step.is-on { opacity: 1; transform: none; }
.wp--js .wp__step.is-on .wp__dot { background: var(--os-color-accent); color: var(--os-color-accent-text); box-shadow: 0 0 0 2px var(--os-color-accent); transform: scale(1.08); }
@media (min-width: 768px) { .wp__rail { left: 27px; top: 29px; bottom: 29px; } .wp__step { padding-left: 110px; } .wp__dot { width: 58px; height: 58px; font-size: 22px; } }
@media (prefers-reduced-motion: reduce) { .wp__step, .wp__dot { transition: none; } }

js:
const wrap = root.querySelector('[data-wp-wrap]');
const fill = root.querySelector('[data-wp-fill]');
const steps = Array.prototype.slice.call(root.querySelectorAll('[data-wp-step]'));
if (!wrap || !fill || ctx.reducedMotion) return;
root.querySelector('.wp').classList.add('wp--js');
let ticking = false;
const update = () => {
  ticking = false;
  const vh = window.innerHeight;
  const mark = vh * 0.62;
  const r = wrap.getBoundingClientRect();
  const p = Math.max(0, Math.min(1, (mark - r.top) / r.height));
  fill.style.transform = 'scaleY(' + p + ')';
  steps.forEach((s) => {
    s.classList.toggle('is-on', s.getBoundingClientRect().top < mark);
  });
};
const onScroll = () => {
  if (!ticking) { ticking = true; requestAnimationFrame(update); }
};
window.addEventListener('scroll', onScroll, { passive: true });
window.addEventListener('resize', onScroll);
update();
